namespace Astrea;

[CreateAssetMenu(fileName = "StellarHasteAchievementData", menuName = "Data/Achievements/StellarHasteAchievementData")]
public class StellarHasteAchievementData : AchievementData
{
	protected override bool UnlockCustomRequirementCheck()
	{
		return ReferenceSingleton<AssetsReference>.Instance.PlayerRunStats.CurrentBattle.BattleTurnCounter == 1;
	}
}
